// Clean Keys from Node 2 & Models from Node 3
let triggerInput = {};
try {
  triggerInput = $('Webhook Trigger').first().json.body || {};
} catch (e) {
  triggerInput = {};
}

const userId = triggerInput.userId || 'default_user';
const connectionId = triggerInput.connectionId || 'Production OpenRouter';
const connectionName = triggerInput.connectionName || 'Production OpenRouter';
const productTag = (triggerInput.productTag || 'SHARED_GATEWAY').toUpperCase();
const environment = (triggerInput.environment || 'production').toLowerCase();

// 1. Extract Keys from Fetch Workspace Keys node
let rawKeys = [];
try {
  const keysNode = $('Fetch Workspace Keys').first().json;
  rawKeys = keysNode.body?.data || keysNode.data || [];
} catch (e) {
  rawKeys = [];
}

let totalLifetimeSpend = 0;
let totalLimit = 0;
let hasLimit = false;
let totalRemaining = 0;

const cleanedKeys = rawKeys.map((k, idx) => {
  const usage = typeof k.usage === 'number' ? Number(k.usage.toFixed(4)) : 0;
  const limit = typeof k.limit === 'number' ? Number(k.limit.toFixed(2)) : null;
  const remaining = typeof k.limit_remaining === 'number'
    ? Number(k.limit_remaining.toFixed(4))
    : (limit !== null ? Math.max(0, Number((limit - usage).toFixed(4))) : null);

  totalLifetimeSpend += usage;
  if (limit !== null) {
    totalLimit += limit;
    hasLimit = true;
  }
  if (remaining !== null) {
    totalRemaining += remaining;
  }

  return {
    keyId: k.hash || k.id || `key_${idx + 1}`,
    name: (k.name || k.label || `Key ${idx + 1}`).trim(),
    label: (k.label || '').trim(),
    createdAt: k.created_at || new Date().toISOString(),
    usage: usage,
    usageDaily: typeof k.usage_daily === 'number' ? Number(k.usage_daily.toFixed(4)) : 0,
    usageWeekly: typeof k.usage_weekly === 'number' ? Number(k.usage_weekly.toFixed(4)) : 0,
    usageMonthly: typeof k.usage_monthly === 'number' ? Number(k.usage_monthly.toFixed(4)) : 0,
    limit: limit,
    remaining: remaining,
    disabled: Boolean(k.disabled),
    workspaceId: k.workspace_id || null,
    environment: environment,
    productTag: productTag
  };
});

// 2. Extract Models from Fetch Analytics Models node
let rawModels = [];
try {
  const modelsNode = $('Fetch Analytics Models').first().json;
  rawModels = modelsNode.body?.data?.data || modelsNode.data?.data || modelsNode.data || [];
} catch (e) {
  rawModels = [];
}

const topModelsBySpend = rawModels.map(m => {
  const cost = typeof m.total_usage === 'number' ? m.total_usage : parseFloat(m.total_usage) || 0;
  const requests = parseInt(m.request_count, 10) || 0;
  const promptTokens = parseInt(m.tokens_prompt, 10) || 0;
  const completionTokens = parseInt(m.tokens_completion, 10) || 0;
  const totalTokens = promptTokens + completionTokens;
  const provider = m.model && m.model.includes('/') ? m.model.split('/')[0] : 'openrouter';

  return {
    name: m.model,
    model: m.model,
    provider: provider.charAt(0).toUpperCase() + provider.slice(1),
    cost: Number(cost.toFixed(4)),
    requests: requests,
    promptTokens: promptTokens,
    completionTokens: completionTokens,
    totalTokens: totalTokens
  };
}).sort((a, b) => b.cost - a.cost);

return {
  success: true,
  userId,
  connectionId,
  connectionName,
  productTag,
  environment,
  totalUsage: Number(totalLifetimeSpend.toFixed(4)),
  creditLimit: hasLimit ? Number(totalLimit.toFixed(2)) : null,
  remainingBalance: hasLimit ? Number(totalRemaining.toFixed(2)) : null,
  cleanedKeys,
  topModelsBySpend
};

// Deduplication & Prepare MongoDB Documents
const input = $json;
if (!input.success) return input;

const { focusRecords, ...meta } = input;

const seenKeys = new Set();
const deduplicatedDocs = [];
let duplicatesPrevented = 0;

for (const doc of (focusRecords || [])) {
  const dedupKey = `${meta.userId}_${doc.resourceId}`;
  if (!seenKeys.has(dedupKey)) {
    seenKeys.add(dedupKey);
    deduplicatedDocs.push(doc);
  } else {
    duplicatesPrevented++;
  }
}

return deduplicatedDocs.map(doc => ({
  ...doc,
  ...meta,
  recordsIngested: deduplicatedDocs.length,
  duplicatesPrevented: duplicatesPrevented,
  lastSyncedAt: new Date().toISOString()
}));
